// Pure parameter-to-geometry evaluation. Base nodes remain available for node editing.
const node=(x,y,extra={})=>({x,y,...extra});
export function componentShape(c){const w=Math.max(5,c.width??86),h=Math.max(5,c.height??100);if(c.kind==='pocket'){const r=Math.min(c.radius??4,w/3,h/3),type=c.style||'patch';let n=[node(r,0),node(w-r,0),node(w,r,{in:{x:w,y:0}}),node(w,h-r),node(w-r,h,{in:{x:w,y:h}}),node(r,h),node(0,h-r,{in:{x:0,y:h}}),node(0,r),node(r,0,{in:{x:0,y:0}})];n.pop();if(type==='back')n=[node(0,0),node(w,0),node(w*.94,h*.8),node(w/2,h),node(w*.06,h*.8)];if(type==='jean')n=[node(0,0),node(w*.8,h*.55,{in:{x:w*.12,y:h*.5}}),node(w,h),node(0,h)];if(type==='kangaroo')n=[node(w*.16,0),node(w*.84,0),node(w,h*.45,{in:{x:w*.88,y:h*.3}}),node(w,h),node(0,h),node(0,h*.45),node(w*.16,0,{in:{x:w*.12,y:h*.3}})].slice(0,-1);if(type==='side')n=[node(0,0),node(w,0),node(w,h),node(w*.2,h),node(w*.1,h*.4,{in:{x:w*.25,y:h*.68}})];if(type==='zip'||type==='diagonalZip')n=[node(0,0),node(w,0),node(w,h*.87),node(w*.88,h,{in:{x:w,y:h}}),node(w*.12,h),node(0,h*.87,{in:{x:0,y:h}})];if(type==='utility')n=[node(0,0),node(w,0),node(w,h),node(w*.55,h),node(w*.45,h*.9),node(0,h*.9)];if(type==='welt'||type==='hidden')n=[node(0,0),node(w,0),node(w,h*.22),node(0,h*.22)];return {nodes:n,closed:true};}
if(c.kind==='hood'){const depth=c.depth??45,opening=c.opening??.7,overlap=c.overlap??0;return {nodes:[node(0,h*.9),node(w*.15,h*.1,{in:{x:-depth*.5,y:h*.6}}),node(w*.85,h*.1,{in:{x:w*.35,y:-h*.12}}),node(w,h*.9,{in:{x:w+depth*.5,y:h*.4}}),node(w*.5+overlap,h,{in:{x:w*.75,y:h*(c.style==='high'?1:1.08)}})],closed:true};}return null;}
